#@ org.scijava.io.IOService ioService

import groovy.json.JsonOutput
import groovy.json.JsonSlurper

// Request and script paths are generated by the backend; no user code is run.
def request = new JsonSlurper().parse(new File(System.getenv('BFS_FIJI_JOB_JSON') ?: ''))
def report = new File(request.output_path as String)
def payload
int exitCode = 0
try {
    def dataset = ioService.open(new File(request.input_path as String).absolutePath)
    if (!(dataset instanceof net.imagej.Dataset)) throw new IllegalArgumentException('Fiji did not return a Dataset')
    def selection = request.selection
    if (dataset.numDimensions() != selection.source_axes.size()) {
        throw new IllegalArgumentException('Dataset axes changed after inspection')
    }
    int xAxis = -1
    int yAxis = -1
    long[] position = new long[dataset.numDimensions()]
    def keys = ['Channel': 'C', 'Z': 'Z', 'Time': 'T']
    for (int axis = 0; axis < dataset.numDimensions(); axis++) {
        String name = dataset.axis(axis).type().getLabel()
        def expected = selection.source_axes[axis]
        if (name != expected.name || dataset.dimension(axis) != (expected.length as long)) {
            throw new IllegalArgumentException('Dataset axes changed after inspection')
        }
        if (name == 'X') xAxis = axis
        else if (name == 'Y') yAxis = axis
        else if (keys.containsKey(name)) position[axis] = (selection.indices[keys[name]] ?: 0) as long
        else if (dataset.dimension(axis) != 1) throw new IllegalArgumentException('Unsupported non-singleton axis')
    }
    if (xAxis < 0 || yAxis < 0) throw new IllegalArgumentException('X/Y axes missing')
    def roi = selection.roi
    long x0 = roi.x as long
    long y0 = roi.y as long
    long width = roi.width as long
    long height = roi.height as long
    if (x0 < 0 || y0 < 0 || width < 1 || height < 1 || width * height > 1000000L ||
            x0 + width > dataset.dimension(xAxis) || y0 + height > dataset.dimension(yAxis)) {
        throw new IllegalArgumentException('ROI outside X/Y bounds or budget')
    }
    if (!(roi.kind in ['rectangle', 'ellipse', 'polygon', 'full'])) {
        throw new IllegalArgumentException('Unsupported ROI kind')
    }
    def imageRoi
    if (roi.kind == 'polygon') {
        def points = roi.points
        if (!(points instanceof List) || points.size() < 3 || points.size() > 32) {
            throw new IllegalArgumentException('Invalid polygon vertices')
        }
        int[] xs = points.collect { it.x as int } as int[]
        int[] ys = points.collect { it.y as int } as int[]
        imageRoi = new ij.gui.PolygonRoi(xs, ys, points.size(), ij.gui.Roi.POLYGON)
        def nativeBounds = imageRoi.getBounds()
        if (nativeBounds.x < x0 || nativeBounds.y < y0 ||
                nativeBounds.x + nativeBounds.width > x0 + width ||
                nativeBounds.y + nativeBounds.height > y0 + height) {
            throw new IllegalArgumentException('Polygon bounds differ from validated vertices')
        }
        x0 = nativeBounds.x
        y0 = nativeBounds.y
        width = nativeBounds.width
        height = nativeBounds.height
        if (width < 1 || height < 1) throw new IllegalArgumentException('Polygon selects no area')
    } else if (roi.kind == 'ellipse') {
        imageRoi = new ij.gui.OvalRoi(x0 as int, y0 as int, width as int, height as int)
    } else {
        imageRoi = new ij.gui.Roi(x0 as int, y0 as int, width as int, height as int)
    }
    def mask = imageRoi.getMask()
    def access = dataset.getImgPlus().randomAccess()
    double sum = 0d
    double min = Double.POSITIVE_INFINITY
    double max = Double.NEGATIVE_INFINITY
    long sampleCount = 0L
    for (long y = y0; y < y0 + height; y++) {
        position[yAxis] = y
        for (long x = x0; x < x0 + width; x++) {
            if (mask != null && mask.getPixel((x - x0) as int, (y - y0) as int) == 0) continue
            position[xAxis] = x
            access.setPosition(position)
            double value = access.get().getRealDouble()
            if (!Double.isFinite(value)) throw new IllegalArgumentException('Non-finite pixel value')
            sampleCount++
            sum += value
            if (value < min) min = value
            if (value > max) max = value
        }
    }
    if (sampleCount < 1L) throw new IllegalArgumentException('ROI selected no pixels')
    // The Fiji menu's ImageJ1 "Measure" entry is ij.plugin.filter.Analyzer.
    // Run that original implementation on the same explicit plane and ROI.
    def imagePlus = ij.IJ.openImage(new File(request.input_path as String).absolutePath)
    if (imagePlus == null) throw new IllegalArgumentException('ImageJ1 could not open source')
    int channels = selection.source_axes.find { it.name == 'Channel' }?.length ?: 1
    int slices = selection.source_axes.find { it.name == 'Z' }?.length ?: 1
    int frames = selection.source_axes.find { it.name == 'Time' }?.length ?: 1
    if (imagePlus.getNChannels() != channels || imagePlus.getNSlices() != slices ||
            imagePlus.getNFrames() != frames) {
        throw new IllegalArgumentException('ImageJ1 plane axes differ from Fiji Dataset')
    }
    imagePlus.setPosition(((selection.indices.C ?: 0) as int) + 1,
            ((selection.indices.Z ?: 0) as int) + 1,
            ((selection.indices.T ?: 0) as int) + 1)
    imagePlus.setRoi(imageRoi)
    def table = new ij.measure.ResultsTable()
    int measures = ij.measure.Measurements.AREA | ij.measure.Measurements.MEAN | ij.measure.Measurements.MIN_MAX
    def extras = selection.extra_measurements ?: []
    if (extras.contains('std_dev')) measures |= ij.measure.Measurements.STD_DEV
    if (extras.contains('median')) measures |= ij.measure.Measurements.MEDIAN
    if (extras.contains('mode')) measures |= ij.measure.Measurements.MODE
    if (extras.contains('integrated_density')) measures |= ij.measure.Measurements.INTEGRATED_DENSITY
    new ij.plugin.filter.Analyzer(imagePlus, measures, table).measure()
    if (table.getCounter() != 1) throw new IllegalStateException('Analyzer did not produce one row')
    def analyzer = [area: table.getValue('Area', 0), area_unit: imagePlus.getCalibration().getUnit() + '^2',
                    mean: table.getValue('Mean', 0),
                    min: table.getValue('Min', 0), max: table.getValue('Max', 0)]
    if (extras.contains('std_dev')) analyzer.std_dev = table.getValue('StdDev', 0)
    if (extras.contains('median')) analyzer.median = table.getValue('Median', 0)
    if (extras.contains('mode')) analyzer.mode = table.getValue('Mode', 0)
    if (extras.contains('integrated_density')) {
        analyzer.integrated_density = table.getValue('IntDen', 0)
        analyzer.raw_integrated_density = table.getValue('RawIntDen', 0)
    }
    for (String key : ['mean', 'min', 'max']) {
        double expected = key == 'mean' ? sum / sampleCount : key == 'min' ? min : max
        if (Math.abs((analyzer[key] as double) - expected) > 1e-8) {
            throw new IllegalStateException('Analyzer differs from Fiji Dataset for ' + key)
        }
    }
    payload = [ok: true, selection: selection, sample_count: sampleCount,
               sum: sum, mean: sum / sampleCount, min: min, max: max,
               imagej1_analyzer: analyzer,
               pixel_type: dataset.getType().class.name,
               bit_depth: dataset.getType().getBitsPerPixel()]
} catch (Throwable error) {
    payload = [ok: false, error_type: error.class.name, message: error.message?.take(240)]
    exitCode = 2
}
report.parentFile.mkdirs()
report.text = JsonOutput.prettyPrint(JsonOutput.toJson(payload)) + '\n'
System.exit(exitCode)
